COPY public.training_pages (training_id, seo_title, seo_description, hero_quote, audience, intro, sections, outcomes, format, faq, created_at, updated_at) FROM stdin;
12	Liderin İlişki Yönetimi ve İletişim Eğitimi | Kurumsal Liderlik Programı	Yöneticiler için ilişki yönetimi ve iletişim eğitimi. Güven inşa eden liderlik iletişimi, aktif dinleme ve ekip içi iletişim becerilerini geliştirin.	Bir liderin en güçlü aracı, söylediği değil; kurduğu bağlantıdır.	Bu program; ekip yönetiminde iletişim zorluğu yaşayan, farklı kişilik tipleriyle çalışmak durumunda olan veya liderlik etkisini derinleştirmek isteyen orta ve üst düzey yöneticiler için tasarlanmıştır.	["Ekibinizle, yöneticilerinizle ve paydaşlarınızla kurduğunuz ilişkilerin kalitesi; motivasyonu, bağlılığı ve performansı doğrudan belirler.", "Bu eğitim, yöneticilerin iletişim tarzlarını bilinçli biçimde şekillendirmelerine ve güvene dayalı ilişki ağları oluşturmalarına yardımcı olmak amacıyla tasarlanmıştır."]	[{"intro": "Liderlik iletişimi sıradan iletişimden farklıdır. Yöneticiler; mesaj iletmenin ötesinde anlam yaratmayı, bağlam kurmayı ve güven ortamı oluşturmayı öğrenir.", "title": "Liderlik İletişiminin Temelleri", "bullets": ["Liderlik iletişimi ile yöneticilik iletişimi arasındaki fark", "Sözlü, sözsüz ve yazılı iletişimde liderlik izlenimi", "Kurumsal iletişimde güven ve şeffaflık ilkesi"]}, {"intro": "Etkili liderler konuşmaktan çok dinlemesini bilir. Aktif dinleme; çalışan bağlılığını artıran, çatışmaları önleyen ve güven inşa eden bir liderlik becerisidir.", "title": "Aktif Dinleme ve Empati", "bullets": ["Aktif dinleme teknikleri ve engelleri", "Empatik iletişim: anlamak ile katılmak arasındaki fark", "Sözsüz iletişim ipuçlarını okuma ve yönetme"]}, {"intro": "Güçlü liderler yalnızca ekipleriyle değil; iç paydaşlar, üst yönetim ve dış çevreyle de sağlıklı ilişkiler sürdürür. Kurumsal ilişki haritası oluşturma ve etkiyi yönetme ele alınır.", "title": "İlişki Yönetimi ve Etki Alanı", "bullets": ["Kurumsal ilişki haritası ve paydaş analizi", "Güven inşasının 3 temel bileşeni", "Zor konuşmaları yapıcı biçimde yönetme"]}, {"intro": "Bireysel iletişim becerileri grup dinamiklerinde farklı bir boyut kazanır. Toplantı yönetimi, geri bildirim kültürü ve açık iletişim ortamı oluşturma ele alınır.", "title": "Ekip İçi ve Grupla İletişim", "bullets": ["Etkili toplantı yönetimi ve katılım sağlama", "Ekip içi açık iletişim kültürü nasıl oluşturulur", "Zor mesajları net ve yapıcı biçimde iletme"]}]	["Liderlik etkisini iletişim üzerinden güçlendirir", "Ekip içinde güven ve açıklık kültürü oluşturur", "Farklı kişilik ve iletişim stilleriyle uyumlu çalışır", "Zor konuşmaları yönetir, çatışmayı önler", "Kurumsal paydaş ilişkilerini stratejik biçimde yönetir"]	[{"label": "Süre", "value": "2 gün (12 saat)"}, {"label": "Format", "value": "Şirket içi veya açık grup"}, {"label": "Yöntem", "value": "Rol yapma ve vaka çalışmaları"}, {"label": "Katılımcı", "value": "8–20 kişi"}]	[{"a": "Tamamen davranışsal ve deneyimsel bir eğitimdir. İçerik psikoloji ve iletişim bilimine dayanmakla birlikte uygulamaya odaklıdır.", "q": "Bu eğitim teknik mi yoksa davranışsal mı?"}, {"a": "Evet. İhtiyaç analizi görüşmesinin ardından kurumunuzun sektörüne, kültürüne ve gerçek vakalarına göre içerik özelleştirilir.", "q": "Eğitim sektöre özel uyarlanabilir mi?"}, {"a": "Evet. Uygulama rehberi ve isteğe bağlı online takip seansı tüm programlara dahildir.", "q": "Eğitim sonrası destek var mı?"}]	2026-07-03 09:57:36.462204+00	\N
13	Takım Çalışması ve Aidiyet Eğitimi | Ekip Motivasyonu ve Bağlılık	Kurumsal aidiyet ve takım çalışması eğitimi. Yüksek performanslı ekipler inşa edin, çalışan bağlılığını artırın. Şirket içi eğitim teklifi alın.	Yüksek performanslı ekipler tesadüfen değil; bilinçli liderlikle kurulur.	Ekip uyumunu ve motivasyonunu artırmak isteyen yöneticiler, yeni kurulan ya da yeniden yapılanan ekiplerin liderleri, çalışan bağlılığı düşük olan departmanların yöneticileri ve İK profesyonelleri için uygundur.	["Ortak bir amaç etrafında birleşen, birbirine güvenen ve kurumuna ait hisseden takımlar; bilinçli bir liderlik anlayışının ürünüdür.", "Bu eğitim; yöneticilere, ekiplerinde gerçek bir aidiyet kültürü oluşturmanın ve sürdürmenin pratik yollarını gösterir."]	[{"intro": "Araştırmalar, yüksek performanslı ekiplerin belirli ortak özellikleri paylaştığını göstermektedir. Bu bölümde Google'ın Project Aristotle bulguları ve Tuckman'ın ekip gelişim modeli ele alınır.", "title": "Yüksek Performanslı Ekibin Anatomisi", "bullets": ["Yüksek performanslı ekibin 5 temel özelliği", "Psikolojik güvenlik ve performans ilişkisi", "Ekip olgunluk aşamaları: Oluşum, çatışma, uyum, performans"]}, {"intro": "Aidiyet; çalışanların kendilerini değerli, görünür ve dahil hissettikleri bir ortamın ürünüdür. Bu bölüm, yöneticilere aidiyet kültürünü inşa etmenin somut adımlarını sunar.", "title": "Aidiyet Kültürü Oluşturma", "bullets": ["Aidiyet ile bağlılık arasındaki fark", "Çeşitlilik içinde dahil edici liderlik", "Takım içi tanınma ve değer görme ritüelleri"]}, {"intro": "Ekip üyeleri, bütünün parçası olduklarını hissettiklerinde daha yüksek performans gösterir. Bu bölümde ortak anlam yaratma ve hedefleri birlikte sahiplenme ele alınır.", "title": "Ortak Amaç ve Hedef Belirleme", "bullets": ["Vizyon ve misyonu ekiple buluşturma", "OKR temelli ekip hedefleri oluşturma", "Bireysel katkıyı büyük resme bağlama"]}, {"intro": "İş birliği, kendiliğinden gelişmez; yapılandırılmış bir ortam gerektirir. Bu bölü